1	<script lang="ts">
2		import { epitaph } from '#lib/epitaph.ts';
3		import type { ApiError, Candidate, Inscription, Story } from '#lib/types.ts';
4	
5		type Phase =
6			'capture' | 'reading' | 'pick' | 'researching' | 'confirm' | 'telling' | 'story' | 'epitaph';
7	
8		const MAX_BYTES = 10 * 1024 * 1024;
9		const TOO_LARGE = 'That photo is over 10 MB. Try a smaller one.';
10		const CONFIDENCE = {
11			high: 'High confidence match',
12			medium: 'Medium confidence match',
13			low: 'Unverified: only the name matches. Check the sources before confirming.'
14		} as const;
15		const NOTES = {
16			none: 'No public record was confirmed',
17			empty: 'No public records were found',
18			insufficient: 'The records hold nothing beyond the stone'
19		} as const;
20	
21		let phase = $state<Phase>('capture');
22		let people = $state<Inscription[]>([]);
23		let person = $state<Inscription | null>(null);
24		let candidates = $state<Candidate[]>([]);
25		let confirmed = $state<Candidate | null>(null);
26		let story = $state<Extract<Story, { status: 'told' }> | null>(null);
27		let epitaphNote = $state<string>(NOTES.none);
28		let message = $state('');
29		let retry = $state<(() => void) | null>(null);
30	
31		/**
32		 * Formats a stored date for display.
33		 * @param date Partial date or null.
34		 * @returns The date, or "unknown".
35		 */
36		function show(date: string | null): string {
37			return date ?? 'unknown';
38		}
39	
40		/**
41		 * Returns to the capture screen, clearing the journey.
42		 * @param note Optional message to show.
43		 */
44		function reset(note = ''): void {
45			phase = 'capture';
46			people = [];
47			person = null;
48			candidates = [];
49			confirmed = null;
50			story = null;
51			message = note;
52			retry = null;
53		}
54	
55		/**
56		 * Shows an error with a retry that re-runs the same request.
57		 * @param text Message for the visitor.
58		 * @param back Phase to return to.
59		 * @param again Action the retry button runs.
60		 */
61		function fail(text: string, back: Phase, again: () => void): void {
62			message = text;
63			phase = back;
64			retry = again;
65		}
66	
67		/**
68		 * Posts to an API endpoint and unwraps errors into messages.
69		 * @param url Endpoint path.
70		 * @param init Fetch options.
71		 * @returns The parsed body.
72		 * @throws {Error} With a visitor-safe message.
73		 */
74		async function call<T>(url: string, init: RequestInit): Promise<T> {
75			let res: Response;
76			try {
77				res = await fetch(url, init);
78			} catch {
79				throw new Error('Could not reach the server. Check your connection.');
80			}
81			const body = await res.json().catch(() => null);
82			if (!res.ok) {
83				if (res.status === 413) throw new Error(TOO_LARGE);
84				throw new Error((body as ApiError | null)?.error.message ?? 'Something went wrong.');
85			}
86			return body as T;
87		}
88	
89		/**
90		 * Uploads the chosen photo and reads the stone.
91		 * @param event Change event from the file input.
92		 */
93		async function onPhoto(event: Event): Promise<void> {
94			const input = event.currentTarget as HTMLInputElement;
95			const file = input.files?.[0];
96			input.value = '';
97			if (!file) return;
98			reset(file.size > MAX_BYTES ? TOO_LARGE : '');
99			if (file.size > MAX_BYTES) return;
100			await read(file);
101		}
102	
103		/**
104		 * Sends the photo to the read endpoint.
105		 * @param file Photo to read.
106		 */
107		async function read(file: File): Promise<void> {
108			phase = 'reading';
109			message = '';
110			retry = null;
111			const form = new FormData();
112			form.set('image', file);
113			try {
114				const res = await call<{ people: Inscription[] }>('/api/read', {
115					method: 'POST',
116					body: form
117				});
118				if (res.people.length === 0) reset('No legible name found. Try another photo.');
119				else if (res.people.length > 1) {
120					people = res.people;
121					phase = 'pick';
122				} else await research(res.people[0]);
123			} catch (e) {
124				fail((e as Error).message, 'capture', () => read(file));
125			}
126		}
127	
128		/**
129		 * Looks up candidate people for one inscription.
130		 * @param p Inscription to research.
131		 */
132		async function research(p: Inscription): Promise<void> {
133			person = p;
134			phase = 'researching';
135			message = '';
136			retry = null;
137			try {
138				const res = await call<{ candidates: Candidate[] }>('/api/research', {
139					method: 'POST',
140					headers: { 'content-type': 'application/json' },
141					body: JSON.stringify(p)
142				});
143				candidates = res.candidates;
144				if (candidates.length === 0) showEpitaph(NOTES.empty);
145				else phase = 'confirm';
146			} catch (e) {
147				fail((e as Error).message, 'researching', () => research(p));
148			}
149		}
150	
151		/**
152		 * Tells the story of the candidate the visitor confirmed.
153		 * @param c Confirmed candidate.
154		 */
155		async function tell(c: Candidate): Promise<void> {
156			if (!person) return;
157			const p = person;
158			confirmed = c;
159			phase = 'telling';
160			message = '';
161			retry = null;
162			try {
163				const res = await call<Story>('/api/story', {
164					method: 'POST',
165					headers: { 'content-type': 'application/json' },
166					body: JSON.stringify({ inscription: p, candidate: c })
167				});
168				if (res.status === 'told') {
169					story = res;
170					phase = 'story';
171				} else showEpitaph(NOTES.insufficient);
172			} catch (e) {
173				fail((e as Error).message, 'confirm', () => tell(c));
174			}
175		}
