		const name = carvedName.replace(MAIDEN, ' ').replace(HONORIFIC, '').replace(/\s+/g, ' ').trim();
		people.push({
			carvedName,
			name,
			maidenName,
			born: partialDateOrNull(p.born),
			died: partialDateOrNull(p.died)
		});
	}
	return people;
}
