11	// Spelled-out numbers compare equal to their digits, so "forty" and "40" support each other.
12	// "one" is left out: "no one" and "one more time" are ordinary prose, not a count.
13	// A Map, not an object: a prose word such as "constructor" must not hit an inherited property.
14	const NUMBER_VALUES = new Map<string, string>([
15		...'two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty'
16			.split(' ')
17			.map((w, i): [string, string] => [w, String(i + 2)]),
18		['thirty', '30'],
19		['forty', '40'],
20		['fifty', '50'],
21		['sixty', '60'],
22		['seventy', '70'],
23		['eighty', '80'],
24		['ninety', '90'],
25		['hundred', '100'],
26		['thousand', '1000']
27	]);
28	
29	// "twenty-four" is one number, so it must equal "24" as a whole; token by token it would not.
30	const TENS = 'twenty thirty forty fifty sixty seventy eighty ninety'.split(' ');
31	const ONES = 'one two three four five six seven eight nine'.split(' ');
32	const COMPOUND_NUMBER = new RegExp(
33		String.raw`\b(${TENS.join('|')})[\s-](${ONES.join('|')})\b`,
34		'giu'
35	);
