41	const MIN_TOPIC_LENGTH = 5;
42	// Compare word stems so "preceded"/"preceding" match without a stemmer dependency.
43	const STEM_LENGTH = 5;
44	// A fact counts as used when at least this share of its topic words appear in the story.
45	const MIN_FACT_USE = 0.5;
