47	// Short function words say nothing about a fact, so a fact with no long words is matched on the rest.
48	const FUNCTION_WORDS = new Set(
49		'a an and are as at be but by for from had has have he her his in is it its of on or she that the their they this to was were who with'.split(
50			' '
51		)
52	);
53	
54	// Life-date words restate the stone's dates, so a quote made of them adds nothing (FR-013).
55	const LIFE_MARKERS = new Set(
56		'born birth died death passed away deceased aged age year years old'.split(' ')
57	);
58	const ORDINAL = /^\d+(?:st|nd|rd|th)$/;
59	
60	// A quote that names survivors would put living people's names into the story (FR-017).
61	const SURVIVORS =
