93	/**
94	 * Lowercases and collapses everything except letters and digits to single spaces.
95	 * @param s Text to normalize.
96	 * @returns Normalized text.
97	 */
98	function norm(s: string): string {
99		return joinCompounds(s)
100			.toLowerCase()
101			.replace(/[^\p{L}\p{N}]+/gu, ' ')
