200		const text = new Map(pages.map((p) => [p.sourceId, norm(p.text)]));
201		const seen = new Set<string>();
202		return raw.filter((f) => {
203			const quote = norm(f.quote ?? '');
204			if (!quote || !known.has(f.sourceId) || !containsPhrase(text.get(f.sourceId) ?? '', quote))
205				return false;
206			if (SURVIVORS.test(f.quote) || namesSurvivor(f.quote)) return false;
