235		inscription: Inscription,
236		candidate: Candidate,
237		facts: VerifiedFact[]
238	): boolean {
239		const names = nameTokens(inscription, candidate);
240		return facts.some((f) =>
241			norm(f.quote)
242				.split(' ')
243				.some((t) => !names.has(t) && !isFiller(t))
244		);
245	}
246	
247	/**
248	 * Checks one sentence for claims the facts do not support: new numbers, new names, or a negation
249	 * attached to a fact. Atmosphere passes untouched.
250	 * @param sentence One sentence of the story.
251	 * @param quoteWords Normalized words of every fact quote.
252	 * @param quoteStems Per-fact topic stems, to tell which fact a sentence is about.
253	 * @param allowed Name and month tokens that need no quote.
254	 * @returns True when the sentence adds nothing the facts lack.
255	 */
256	function sentenceHolds(
257		sentence: string,
258		quoteWords: Set<string>,
259		quoteStems: { stems: Set<string>; words: Set<string> }[],
260		allowed: Set<string>
261	): boolean {
262		const words = joinCompounds(sentence).match(/[\p{L}\p{N}]+/gu) ?? [];
263		const lower = words.map((w) => w.toLowerCase());
264		// Short content words count too, so a fact made of short words is still found by a negation check.
265		const topics = new Set([
266			...topicStems(lower.join(' ')),
267			...lower.filter((w) => !FUNCTION_WORDS.has(w))
268		]);
269		const about = quoteStems.filter((q) => [...topics].some((t) => q.stems.has(t)));
270		for (const [i, word] of words.entries()) {
271			const w = lower[i];
272			const known = quoteWords.has(canon(w)) || allowed.has(w);
