274			const properNoun = i > 0 && /^\p{Lu}/u.test(word) && w !== 'i';
275			if ((number || properNoun) && !known) return false;
276			if (NEGATIONS.has(w) && about.length > 0 && !about.some((q) => q.words.has(w))) return false;
277		}
278		return true;
279	}
