121		// "May" and "March" are capitalized words that are not names.
122		const bare = quote.replace(MONTH_WORD, ' ');
123		return NAMED_RELATIVE_CASE.test(bare) && NAMED_RELATIVE.test(bare) && !PREDECEASED.test(bare);
