125	
126	/**
127	 * Rewrites spelled-out compound numbers as digits: "twenty-four" becomes "24".
128	 * @param text Any text.
129	 * @returns The text with each tens-and-ones number written as one numeral.
130	 */
131	function joinCompounds(text: string): string {
132		return text.replace(COMPOUND_NUMBER, (_, tens: string, ones: string) =>
133			String((TENS.indexOf(tens.toLowerCase()) + 2) * 10 + ONES.indexOf(ones.toLowerCase()) + 1)
