267			...lower.filter((w) => !FUNCTION_WORDS.has(w))
268		]);
269		const about = quoteStems.filter((q) => [...topics].some((t) => q.stems.has(t)));
270		for (const [i, word] of words.entries()) {
271			const w = lower[i];
272			const known = quoteWords.has(canon(w)) || allowed.has(w);
273			const number = /^\d+$/.test(w) || NUMBER_VALUES.has(w);
274			const properNoun = i > 0 && /^\p{Lu}/u.test(word) && w !== 'i';
275			if ((number || properNoun) && !known) return false;
276			if (NEGATIONS.has(w) && about.length > 0 && !about.some((q) => q.words.has(w))) return false;
277		}
278		return true;
279	}
280	
281	/**
282	 * Splits a paragraph into sentences.
283	 * @param paragraph Prose as the model wrote it.
284	 * @returns Trimmed, non-empty sentences.
285	 */
286	function sentencesOf(paragraph: string): string[] {
287		return paragraph
