291	}
292	
293	/**
294	 * Drops sentences that add claims the verified facts do not support, then checks the story still
295	 * uses the facts and lists the sources it draws on.
296	 * @param inscription The stone's person.
297	 * @param candidate The confirmed candidate.
298	 * @param facts Verified facts the paragraph was written from.
299	 * @param paragraph The paragraph as the model wrote it.
300	 * @returns A told story, or `insufficient` when no real fact survives in it.
301	 */
302	export function groundParagraph(
303		inscription: Inscription,
304		candidate: Candidate,
305		facts: VerifiedFact[],
306		paragraph: string
307	): Story {
308		if (!hasEvidence(inscription, candidate, facts)) return { status: 'insufficient' };
309		const normed = facts.map((f) => norm(f.quote));
310		const quoteWords = new Set(normed.flatMap((q) => q.split(' ').map(canon)));
311		const quoteStems = normed.map((q) => ({
312			stems: new Set(factTerms(q)),
313			terms: factTerms(q),
314			words: new Set(q.split(' '))
315		}));
316		const allowed = new Set([...nameTokens(inscription, candidate), ...MONTHS]);
317	
318		const seen = new Set<string>();
319		const kept = sentencesOf(paragraph).filter((s) => {
320			const key = norm(s);
321			if (seen.has(key)) return false;
322			seen.add(key);
323			return sentenceHolds(s, quoteWords, quoteStems, allowed);
324		});
325		const body = kept.join(' ');
326	
327		const present = new Set(
328			norm(body)
329				.split(' ')
330				.map((w) => canon(w).slice(0, STEM_LENGTH))
331		);
332		const used = facts.filter((f, i) => {
333			const { terms } = quoteStems[i];
334			return (
335				terms.length > 0 && terms.filter((t) => present.has(t)).length / terms.length >= MIN_FACT_USE
336			);
337		});
338		if (!hasEvidence(inscription, candidate, used)) return { status: 'insufficient' };
339		const cited = new Set(used.map((f) => f.sourceId));
340		return {
341			status: 'told',
342			paragraph: body,
343			sources: candidate.sources.filter((s) => cited.has(s.id))
344		};
345	}
