75	 * Lowercases text and folds accents so "Ødegård" and "odegard" compare equal.
76	 * @param text Text to fold.
77	 * @returns Folded text.
78	 */
79	function fold(text: string): string {
80		const letters: Record<string, string> = { æ: 'ae', œ: 'oe', ø: 'o', ß: 'ss', đ: 'd', ł: 'l' };
81		return text
82			.normalize('NFD')
83			.replace(/\p{M}+/gu, '')
84			.toLowerCase()
85			.replace(/[æœøßđł]/g, (c) => letters[c]);
86	}
87	
88	/**
89	 * Splits a name into given names and a surname, ignoring generational suffixes.
90	 * @param name Full name.
91	 * @returns Folded given-name tokens and surname.
92	 */
93	function nameParts(name: string): { given: string[]; surname: string } {
94		// A quoted nickname (Corwin "Cory" Chambers) is another given name a record may use.
95		const parts = fold(name)
96			.replace(/[.,"“”]/g, ' ')
97			.split(/\s+/)
98			.filter(Boolean);
99		while (parts.length > 1 && NAME_SUFFIXES.has(parts.at(-1)!)) parts.pop();
100		const surname = parts.pop() ?? '';
101		return { given: parts, surname };
102	}
103	
104	/**
105	 * Finds every whole-word occurrence of a word.
106	 * @param text Folded text.
107	 * @param word Folded word.
108	 * @returns Indexes of the occurrences.
109	 */
110	function wordIndexes(text: string, word: string): number[] {
111		if (!word) return [];
112		const escaped = word.replace(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);
113		const found = text.matchAll(
114			new RegExp(String.raw`(?<![\p{L}\p{N}])${escaped}(?![\p{L}\p{N}])`, 'gu')
115		);
116		return [...found].map((m) => m.index);
117	}
118	
119	/**
120	 * Splits text into words at whitespace, quotes and parentheses, so "Gaynor (Staples) Hawks" reads as one name.
121	 * @param chunk Text to split.
122	 * @param offset Index of the chunk within the full text.
123	 * @returns Words with their index in the full text.
124	 */
125	function wordsOf(chunk: string, offset: number): { word: string; index: number }[] {
126		return [...chunk.matchAll(/[^\s"“”()]+/gu)].map((m) => ({ word: m[0], index: offset + m.index }));
127	}
128	
129	/**
130	 * Classifies a word as part of a personal name.
131	 * @param word A word from the text.
132	 * @returns The bare name, and whether trailing punctuation ends the name; null for other words.
133	 */
134	function namePart(word: string): { name: string; closes: boolean } | null {
135		const name = word.replace(/[.,]$/, '');
136		if (!NAME_WORD.test(name)) return null;
137		return { name, closes: name !== word && !(word.endsWith('.') && name.length === 1) };
138	}
139	
140	/**
141	 * Tells whether a word from a record can be one of the stone's given names.
142	 * @param given Folded given names of the stone; an initial stands for any name that starts with it.
143	 * @param word Folded word from the record.
144	 * @returns True for an exact match, or when the stone carries only the initial.
145	 */
146	function isGiven(given: string[], word: string): boolean {
147		return given.some((g) => g === word || (g.length === 1 && word.startsWith(g)));
148	}
149	
150	/**
151	 * Finds where the name phrase containing a surname starts, if a given name is in that phrase.
152	 * @param text Folded text.
153	 * @param given Folded given names of the stone.
154	 * @param at Index of the surname occurrence.
155	 * @param length Length of the surname.
156	 * @returns Index where the phrase starts, or -1 when no given name sits in the same phrase.
157	 */
158	function phraseStart(text: string, given: string[], at: number, length: number): number {
159		if (!given.length) return at;
160		const from = Math.max(0, at - NAME_REACH);
161		let first = at;
162		let hit = false;
163		for (const w of wordsOf(text.slice(from, at), from).reverse().slice(0, NAME_WORDS_MAX)) {
164			const part = namePart(w.word);
165			if (!part || part.closes || PREFIX_WORDS.has(part.name)) break;
166			first = w.index;
167			hit ||= isGiven(given, part.name);
168		}
169		if (hit) return first;
170		// "Surname, Given" counts only when the surname opens its phrase; otherwise
171		// "Charles Hawks, Gaynor Jones" would pair Hawks with Gaynor.
172		if (first !== at || text[at + length] !== ',') return -1;
173		const next = at + length + 1;
174		for (const w of wordsOf(text.slice(next, next + NAME_REACH), next).slice(0, NAME_WORDS_MAX - 1)) {
175			const part = namePart(w.word);
176			if (!part) break;
177			if (isGiven(given, part.name)) return at;
178			if (part.closes) break;
179		}
180		return -1;
181	}
182	
183	/**
184	 * Lists the years a result allows that agree with a stone year, where `?` matches any digit.
185	 * @param stone Stone year, possibly with `?` digits.
186	 * @param found Latest year the result allows.
187	 * @param slack Years the true year may lie before `found`, for years derived from an age.
188	 * @returns Agreeing years; empty when none can denote the same year.
189	 */
190	function agreeingYears(stone: string, found: number, slack = 0): number[] {
191		const years: number[] = [];
192		for (let y = found - slack; y <= found; y++) {
193			if ([...stone].every((c, i) => c === '?' || c === String(y)[i])) years.push(y);
194		}
195		return years;
196	}
197	
198	/**
199	 * Finds the year that follows a cue word such as "born" or "died".
200	 * @param text Folded text.
201	 * @param cue Regular-expression source for the cue words.
202	 * @returns The year, or null.
203	 */
