 */
function nameTokens(inscription: Inscription, candidate?: Candidate): Set<string> {
	return new Set(
		[inscription.name, candidate?.name ?? '', inscription.maidenName ?? '']
			.flatMap((n) => norm(n).split(' '))
			.filter(Boolean)
	);
